export const DEVICES_INTERNET_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu perangkat digital",q:"'Perangkat digital' adalah...",options:["Alat elektronik yang bisa menyimpan & mengolah informasi, seperti HP, laptop, tablet, & komputer","Semua benda yang memakai listrik atau baterai, termasuk kulkas, lampu, dan kipas angin","Hanya telepon seluler yang bisa dipakai untuk menelepon dan mengirim pesan"],answer:0,explain:"Perangkat digital menjalankan program & menyimpan data. Kulkas biasa memakai listrik tapi bukan perangkat digital dalam arti ini.",hint:"Menyimpan & mengolah informasi, atau sekadar memakai listrik?"},
{n:2,type:"mcq",micro:"Bagian perangkat",q:"Bagian yang menyimpan foto, aplikasi, & file di HP disebut...",options:["Baterai","Penyimpanan (storage/memori internal)","Layar"],answer:1,explain:"Penyimpanan menahan data meski HP dimatikan. Layar menampilkan, baterai memberi tenaga.",hint:"Yang menahan data walau HP mati, atau yang menampilkan?"},
{n:3,type:"mcq",micro:"RAM vs penyimpanan",q:"Beda 'RAM' (memori sementara) dengan 'penyimpanan':",options:["Keduanya sama: sama-sama hanya menyimpan file dan tetap ada saat perangkat dimatikan","RAM menyimpan foto dan dokumen dalam jangka panjang, sedangkan penyimpanan hanya untuk aplikasi yang sedang berjalan","RAM dipakai untuk hal yang sedang berjalan sekarang & kosong saat dimatikan; penyimpanan menahan file secara tetap"],answer:2,explain:"RAM seperti meja kerja (yang sedang dipakai); penyimpanan seperti lemari arsip (disimpan lama).",hint:"RAM sementara & penyimpanan tetap, atau sama saja?"},
{n:4,type:"mcq",micro:"Apa itu internet",q:"'Internet' paling tepat digambarkan sebagai...",options:["Jaringan raksasa yang menghubungkan jutaan perangkat & server di seluruh dunia sehingga bisa saling bertukar data","Satu komputer besar milik satu perusahaan yang dipakai bersama oleh seluruh dunia lewat kabel","Aplikasi di HP yang dipakai untuk menjelajah, mengirim pesan, dan menyimpan data antar pengguna ponsel"],answer:0,explain:"Internet adalah jaringan dari jaringan. Tidak ada satu pemilik; ia adalah infrastruktur bersama.",hint:"Jaringan global antar perangkat, atau satu komputer besar?"},
{n:5,type:"mcq",micro:"Internet vs Web",q:"'Web' (World Wide Web) adalah...",options:["Nama lain untuk internet, yaitu seluruh kabel dan jaringan yang menghubungkan perangkat di dunia","Salah satu layanan yang berjalan di atas internet, yaitu halaman-halaman yang dibuka lewat browser","Aplikasi pesan khusus yang dipasang lewat toko aplikasi dan hanya jalan di satu jenis HP"],answer:1,explain:"Internet adalah jalannya; web adalah salah satu kendaraan di jalan itu. Email & video call juga memakai internet tapi bukan web.",hint:"Layanan di atas internet, atau sama dengan internet?"},
{n:6,type:"mcq",micro:"Wi-Fi vs data seluler",q:"Beda menghubungkan ke internet lewat Wi-Fi & lewat data seluler:",options:["Wi-Fi memakai kuota operator seluler, sedangkan data seluler lewat jaringan lokal rumah atau sekolah dan gratis","Keduanya sama-sama memakai kuota dari operator seluler, bedanya hanya pada kecepatan yang didapat","Wi-Fi lewat jaringan lokal (rumah/sekolah) biasanya tanpa kuota terpisah; data seluler lewat operator & memakai kuota"],answer:2,explain:"Wi-Fi butuh berada dalam jangkauan pemancarnya; data seluler bekerja di mana ada sinyal operator tapi memakai paket data.",hint:"Jaringan lokal vs operator + kuota, atau sama saja?"},
{n:7,type:"mcq",micro:"Browser",q:"'Browser' (peramban) adalah aplikasi untuk...",options:["Membuka & menampilkan halaman web, mis. Chrome, Firefox, Safari, Edge","Menyimpan foto dan video dari kamera ke dalam galeri perangkat","Menelepon dan mengirim pesan teks ke nomor kontak yang tersimpan"],answer:0,explain:"Browser menerjemahkan kode halaman web jadi tampilan yang bisa kita baca & klik.",hint:"Membuka halaman web, atau menyimpan foto?"},
{n:8,type:"mcq",micro:"Alamat web (URL)",q:"Bagian 'https://' di depan alamat web menandakan...",options:["Bahwa isi situs itu sudah dipastikan benar dan tepercaya","Cara komunikasi terenkripsi (lebih aman) antara browser & situs","Nama pemilik situs beserta alamat kantor pusatnya"],answer:1,explain:"'https' berarti sambungannya dienkripsi (data sulit disadap). Tapi ini TIDAK menjamin isi situsnya jujur atau aman.",hint:"Sambungan terenkripsi, atau jaminan situs jujur?"},
{n:9,type:"order",micro:"Membuka sebuah halaman web",q:"Urutkan yang terjadi saat kamu mengetik alamat web & menekan Enter.",items:["Browser mencari alamat server yang menyimpan situs itu","Browser mengirim permintaan ke server tersebut lewat internet","Server mengirim balik kode halaman (teks, gambar, dll)","Browser menyusun kode itu jadi tampilan yang kamu lihat"],answer:[0,1,2,3],explain:"Cari alamat server → minta halaman → server kirim → browser menampilkan. Semua dalam hitungan detik.",hint:"Server mengirim halaman sebelum atau sesudah browser meminta?"},
{n:10,type:"mcq",micro:"Aplikasi vs situs web",q:"Beda 'aplikasi' (app) yang dipasang dengan 'situs web' yang dibuka di browser:",options:["Keduanya sama persis, sama-sama harus diunduh dan dipasang dulu di perangkat sebelum bisa dipakai","Aplikasi tidak butuh internet, sedangkan situs web butuh internet dan harus dipasang","Aplikasi diunduh & terpasang di perangkat; situs web dibuka lewat browser tanpa dipasang"],answer:2,explain:"Banyak aplikasi tetap butuh internet untuk sebagian fungsinya. Bedanya terutama pada terpasang vs dibuka lewat browser.",hint:"Terpasang vs dibuka di browser, atau sama saja?"},
{n:11,type:"tf",micro:"Internet tanpa pemilik tunggal",q:"Benar atau Salah: Internet tidak dimiliki atau dikendalikan sepenuhnya oleh satu perusahaan atau satu negara.",answer:true,explain:"Internet adalah jaringan bersama yang dijalankan oleh banyak pihak (operator, penyedia, organisasi) yang menyepakati aturan teknis yang sama.",hint:"Bersama & banyak pihak, atau milik satu perusahaan?"},
{n:12,type:"tf",micro:"Semua di HP butuh internet?",q:"Benar atau Salah: Semua aplikasi & fungsi di HP membutuhkan koneksi internet untuk bekerja.",answer:false,explain:"Sebaliknya, banyak yang bekerja luring (offline): kalkulator, kamera, catatan, sebagian permainan, memutar musik yang sudah diunduh.",hint:"Semua butuh internet, atau banyak yang luring?"},
{n:13,type:"mcq",micro:"Baterai",q:"Cara memperlambat pengurasan baterai HP:",options:["Turunkan kecerahan layar, tutup aplikasi yang tidak dipakai, matikan lokasi/Wi-Fi/Bluetooth saat tidak perlu","Isi daya sampai 100% lalu cabut segera, dan naikkan kecerahan layar sampai paling terang","Biarkan semua aplikasi terbuka di latar belakang, nyalakan semua sensor, dan pakai layar paling terang"],answer:0,explain:"Layar & radio (Wi-Fi, data, GPS) adalah pengguna daya terbesar. Mengelolanya memperpanjang daya tahan.",hint:"Kurangi layar & radio yang tidak perlu, atau biarkan semua terbuka?"},
{n:14,type:"mcq",micro:"Menyimpan lokal vs awan",q:"'Menyimpan di awan (cloud)' berarti...",options:["File hanya ada di HP-mu sendiri sehingga tidak bisa dibuka dari perangkat lain mana pun","File disimpan di server penyedia lewat internet, sehingga bisa diakses dari perangkat lain","File disimpan di langit lewat awan sungguhan, sehingga cuaca bisa memengaruhi berkasmu setiap hari"],answer:1,explain:"Cloud = komputer orang lain (server) yang kamu percayai untuk menyimpan datamu. Butuh internet untuk mengaksesnya.",hint:"Di server lewat internet, atau hanya di HP?"},
{n:15,type:"mcq",micro:"Akun",q:"Kegunaan 'akun' (dengan email/nama pengguna & kata sandi) pada layanan digital:",options:["Sekadar hiasan di layar; data dan pengaturanmu tidak tersimpan di layanan itu","Membuat layanan berjalan lebih cepat karena pemakai tanpa akun dibatasi kecepatan aksesnya oleh penyedia","Mengenali kamu & menyimpan data serta pengaturanmu, sehingga bisa dilanjutkan di perangkat lain"],answer:2,explain:"Akun mengikat datamu ke identitas digital. Menjaga kata sandinya berarti menjaga akses ke data itu.",hint:"Mengenali & menyimpan datamu, atau formalitas?"},
{n:16,type:"tf",micro:"Mode pesawat",q:"Benar atau Salah: 'Mode pesawat' hanya mematikan panggilan telepon, sementara Wi-Fi & Bluetooth tetap menyala seperti biasa.",answer:false,explain:"Sebaliknya, mode pesawat memutus semua radio pemancar/penerima (data seluler, Wi-Fi, Bluetooth) sekaligus. Kamu bisa menyalakan lagi Wi-Fi atau Bluetooth secara terpisah setelahnya bila diizinkan.",hint:"Mematikan semua koneksi nirkabel, atau hanya telepon?"},
{n:17,type:"mcq",micro:"Sistem operasi",q:"'Sistem operasi' (mis. Android, iOS, Windows) adalah...",options:["Perangkat lunak dasar yang mengatur seluruh perangkat & menjadi tempat aplikasi lain berjalan","Sebuah aplikasi biasa yang bisa dipasang dan dihapus kapan saja oleh pemakai perangkat","Nama merek HP yang dipakai pabrik untuk membedakan produk dari pesaingnya"],answer:0,explain:"Sistem operasi mengelola layar, penyimpanan, jaringan, & memberi 'panggung' bagi aplikasi.",hint:"Perangkat lunak dasar pengatur, atau aplikasi biasa?"},
{n:18,type:"mcq",micro:"Memperbarui perangkat",q:"Kenapa penting memasang pembaruan (update) sistem & aplikasi?",options:["Pembaruan hanya mengganti tampilan dan ikon, sehingga boleh dilewatkan tanpa risiko untuk keamanan","Pembaruan sering menutup lubang keamanan & memperbaiki bug, selain menambah fitur","Pembaruan memperlambat perangkat dan menghabiskan kuota, jadi sebaiknya dimatikan permanen"],answer:1,explain:"Banyak serangan memanfaatkan celah lama yang sudah ditambal di versi baru. Menunda pembaruan membiarkan celah itu terbuka.",hint:"Menutup celah keamanan, atau membuang kuota?"},
{n:19,type:"mcq",micro:"Kecepatan internet",q:"Kalau halaman web lambat terbuka, penyebab yang mungkin:",options:["Biasanya karena HP-nya rusak, sehingga langkah yang tepat adalah segera membeli perangkat yang baru lagi","Halaman lambat terbuka secara acak, dan alasannya tidak bisa dicari atau diperiksa oleh pemakainya","Sinyal lemah, banyak perangkat memakai jaringan yang sama, kuota habis/diperlambat, atau situs itu sendiri sedang sibuk"],answer:2,explain:"Kecepatan terpengaruh banyak hal: sinyal, beban jaringan, kebijakan operator, & kondisi server tujuan.",hint:"Beberapa penyebab mungkin, atau selalu HP rusak?"},
{n:20,type:"open",micro:"Petakan perangkat & koneksimu",q:"Pilih satu perangkat yang kamu pakai. Jelaskan: (a) jenisnya & 3 bagian utamanya beserta fungsinya, (b) cara ia terhubung ke internet (Wi-Fi/data/keduanya) & kapan masing-masing dipakai, (c) 2 hal yang bisa ia lakukan tanpa internet & 2 yang butuh internet, (d) satu kebiasaan yang akan kamu terapkan untuk merawatnya (baterai, penyimpanan, atau pembaruan).",explain:"Jawaban baik: jenis perangkat + 3 bagian dengan fungsi yang benar, penjelasan koneksi yang membedakan Wi-Fi & data serta kapan dipakai, 2+2 contoh luring/daring yang tepat, & satu kebiasaan perawatan yang spesifik & bisa dilakukan.",hint:"Untuk (c), ingat: memotret & kalkulator luring; peta rute baru & streaming butuh internet.",sample:"(a) Perangkat: HP Android. Bagian utama: layar (menampilkan & menerima sentuhan), penyimpanan internal 64 GB (menahan aplikasi, foto, & file walau HP mati), baterai (memberi tenaga; makin sering layar menyala makin cepat habis). (b) Koneksi: HP-ku bisa lewat Wi-Fi & data seluler. Di rumah & sekolah aku pakai Wi-Fi supaya hemat kuota; di jalan atau tempat tanpa Wi-Fi aku pakai data seluler dengan paket bulanan. (c) Tanpa internet: memotret, membuka catatan & kalkulator, memutar lagu yang sudah diunduh, bermain satu game luring. Butuh internet: membuka peta & mencari rute baru, mengirim pesan lewat aplikasi chat, menonton video streaming, memperbarui aplikasi. (d) Kebiasaan merawat: aku akan menyalakan pembaruan otomatis aplikasi hanya saat terhubung Wi-Fi, & sekali seminggu memeriksa penyimpanan, menghapus foto ganda & file unduhan yang tidak lagi kubutuhkan supaya penyimpanan tidak penuh & HP tidak lambat."},
{n:21,type:"classify",micro:"Butuh internet vs bisa luring",q:"Kelompokkan tiap aktivitas ke 'Butuh internet' atau 'Bisa dilakukan luring'.",items:["Mengirim pesan lewat aplikasi chat","Memakai kalkulator bawaan","Menonton video streaming","Membuka foto yang tersimpan di HP"],groups:["Butuh internet","Bisa dilakukan luring"],answer:{"Butuh internet":["Mengirim pesan lewat aplikasi chat","Menonton video streaming"],"Bisa dilakukan luring":["Memakai kalkulator bawaan","Membuka foto yang tersimpan di HP"]},explain:"Butuh internet: apa pun yang mengirim/menerima data dari luar perangkat saat itu. Luring: yang datanya sudah ada di perangkat.",hint:"Mengirim/menerima data dari luar, atau data sudah di perangkat?"},
{n:22,type:"mcq",micro:"Data dikirim dalam potongan",q:"Saat kamu mengirim file lewat internet, file itu...",options:["Dipecah jadi banyak paket kecil yang dikirim terpisah lalu disusun ulang di tujuan","Dikirim utuh dalam satu potong besar tanpa dipecah, lalu langsung diterima oleh tujuan tanpa perantara","Disalin ke setiap komputer di dunia lebih dulu, baru kemudian sampai ke komputer yang kamu tuju"],answer:0,explain:"Pemecahan jadi paket membuat pengiriman lebih andal: kalau satu paket hilang, hanya itu yang dikirim ulang.",hint:"Paket-paket kecil, atau satu potong besar?"},
{n:23,type:"mcq",micro:"Server & klien",q:"Dalam 'klien meminta, server melayani', HP-mu yang membuka Instagram berperan sebagai...",options:["Keduanya server yang menyimpan dan mengirim data, tidak ada yang meminta","Klien (yang meminta); server Instagram yang menyimpan & mengirim data","Server yang meminta dan klien Instagram yang menyimpan data"],answer:1,explain:"Klien = perangkat yang meminta layanan. Server = komputer yang menyimpan data & menjawab permintaan.",hint:"Klien yang meminta, atau server yang melayani?"},
{n:24,type:"mcq",micro:"Router & modem",q:"Fungsi 'router' Wi-Fi di rumah:",options:["Menyimpan seluruh data internet dunia dalam satu perangkat kecil di rumah pemakai","Membuat listrik dari sinyal Wi-Fi supaya perangkat tidak perlu dicas","Membagikan satu koneksi internet ke banyak perangkat sekaligus lewat sinyal Wi-Fi & kabel"],answer:2,explain:"Router mengatur lalu lintas data antara perangkat di rumah & internet luar, & memberi tiap perangkat 'jalur'.",hint:"Membagi koneksi ke banyak perangkat, atau menyimpan data dunia?"},
{n:25,type:"mcq",micro:"ISP",q:"'Penyedia layanan internet' (ISP) adalah...",options:["Perusahaan yang menyambungkan rumah/HP-mu ke internet yang lebih luas, mis. lewat kabel atau jaringan seluler","Pembuat HP yang menyediakan sistem operasi dan aplikasi bawaan untuk perangkatmu","Situs web yang menyediakan mesin pencari dan layanan email untuk semua pemakai internet di dunia"],answer:0,explain:"ISP adalah 'gerbang'-mu ke internet. Kamu membayar mereka untuk akses; mereka menyambungkan ke jaringan global.",hint:"Menyambungkanmu ke internet, atau membuat HP?"},
{n:26,type:"mcq",micro:"Alamat IP",q:"'Alamat IP' sebuah perangkat berfungsi seperti...",options:["Kata sandi, agar hanya pemilik yang boleh memakai perangkat itu","Alamat rumah, agar data tahu harus dikirim ke perangkat yang mana","Nama pemiliknya, agar perangkat bisa dikenali saat sedang online"],answer:1,explain:"Setiap perangkat di jaringan punya alamat IP sehingga paket data bisa menemukan tujuannya.",hint:"Alamat tujuan data, atau kata sandi?"},
{n:27,type:"tf",micro:"Wi-Fi publik lebih berisiko",q:"Benar atau Salah: Menggunakan Wi-Fi publik gratis (mal, kafe) untuk hal sensitif seperti perbankan sama amannya dengan memakai data seluler pribadi.",answer:false,explain:"Sebaliknya, Wi-Fi publik bisa dipakai bersama orang tak dikenal & kadang tidak aman, jadi lebih berisiko. Untuk hal sensitif, data seluler pribadi atau jaringan tepercaya lebih baik.",hint:"Lebih berisiko, atau sama saja?"},
{n:28,type:"tf",micro:"Menghapus aplikasi vs data",q:"Benar atau Salah: Menghapus (uninstall) sebuah aplikasi dari HP juga otomatis menghapus semua data terkaitnya yang tersimpan di server/akun online.",answer:false,explain:"Sebaliknya, uninstall hanya menghapus aplikasi dari perangkat. Data di akun online (foto, riwayat) sering tetap ada sampai kamu menghapusnya lewat pengaturan akun.",hint:"Data online ikut terhapus, atau tetap ada di server?"},
{n:29,type:"mcq",micro:"Cache",q:"'Cache' aplikasi/browser adalah...",options:["File penting milik sistem yang tidak boleh dihapus karena penghapusannya bisa merusak aplikasi lain","Virus kecil yang menumpang di aplikasi dan harus segera dibersihkan dengan antivirus","Salinan sementara data (gambar, halaman) agar pemuatan berikutnya lebih cepat; bisa dibersihkan bila penyimpanan penuh"],answer:2,explain:"Cache mempercepat, tapi menumpuk. Membersihkannya aman & sering membebaskan ruang; data akan diunduh ulang saat dibutuhkan.",hint:"Salinan sementara untuk mempercepat, atau file penting?"},
{n:30,type:"order",micro:"Data mengalir saat menonton video",q:"Urutkan alur saat kamu menonton video daring.",items:["Kamu menekan putar; aplikasi mengirim permintaan ke server video","Server mulai mengirim video dalam potongan-potongan","Perangkatmu menyimpan sedikit di depan (buffer) lalu mulai memutar","Selama menonton, potongan berikutnya terus diunduh mengikuti"],answer:[0,1,2,3],explain:"Minta → server kirim bertahap → buffer & mulai putar → unduh berkelanjutan. Buffer inilah yang 'habis' saat koneksi lambat & video berhenti.",hint:"Buffer terisi sebelum atau sesudah video mulai diputar?"},
{n:31,type:"mcq",micro:"Sinkronisasi",q:"'Sinkronisasi' (sync) akun berarti...",options:["Perubahan di satu perangkat otomatis tercermin di perangkat lain lewat server, mis. kontak & foto","Menyalin data ke HP teman lewat Bluetooth secara otomatis tiap kali kamu terhubung","Mematikan koneksi internet supaya data lama tidak bercampur dengan data baru"],answer:0,explain:"Sync menjaga data konsisten di semua perangkat yang memakai akun sama. Menghapus di satu tempat bisa menghapus di semua.",hint:"Data konsisten antar perangkat, atau menyalin ke HP teman?"},
{n:32,type:"tf",micro:"Kapasitas penyimpanan terbatas",q:"Benar atau Salah: Penyimpanan HP yang hampir penuh tidak berpengaruh apa-apa pada kecepatan perangkat atau kemampuan aplikasi bekerja.",answer:false,explain:"Sebaliknya, sistem butuh ruang kosong untuk bekerja. Penyimpanan penuh bisa membuat perangkat lambat, aplikasi gagal terbuka, & kamera tidak bisa memotret. Menghapus file/aplikasi yang tak dipakai membantu.",hint:"Menyebabkan lambat & gagal, atau tidak berpengaruh?"},
{n:33,type:"mcq",micro:"Peramban & tab",q:"Membuka terlalu banyak tab browser sekaligus bisa...",options:["Tidak memengaruhi kinerja, karena tab yang tidak dilihat berhenti memakai memori","Menghabiskan RAM & membuat perangkat lambat, karena tiap tab memakai memori","Mempercepat perangkat, karena banyak tab membuat halaman siap pakai"],answer:1,explain:"Tiap tab adalah halaman aktif di memori. Menutup yang tidak dipakai membebaskan sumber daya.",hint:"Menghabiskan memori, atau mempercepat?"},
{n:34,type:"mcq",micro:"Notifikasi",q:"Mengelola notifikasi aplikasi berguna karena...",options:["Notifikasi tidak bisa diatur oleh pemakai, jadi setiap aplikasi akan terus mengirim pemberitahuan","Semua notifikasi sebaiknya dinyalakan agar informasi tidak terlewat, walau mengganggu fokus","Mengurangi gangguan, menghemat baterai, & membantu fokus; kamu bisa mematikan yang tidak penting"],answer:2,explain:"Kebanyakan sistem membiarkanmu memilih aplikasi mana yang boleh mengganggu. Menyaringnya adalah kendali yang berharga.",hint:"Bisa diatur & disaring, atau harus semua nyala?"},
{n:35,type:"mcq",micro:"Kuota & pemakaian data",q:"Aktivitas yang paling banyak memakai kuota data:",options:["Menonton video & panggilan video dalam kualitas tinggi","Mengirim pesan teks dan mengatur alarm di perangkat","Membuka halaman web sederhana dan membaca artikel pendek"],answer:0,explain:"Video adalah pemakai data terbesar. Menurunkan kualitas video atau memakainya hanya saat Wi-Fi menghemat kuota.",hint:"Video kualitas tinggi, atau pesan teks?"},
{n:36,type:"mcq",micro:"Perangkat lambat seiring waktu",q:"Kenapa perangkat bisa terasa lebih lambat setelah dipakai bertahun-tahun?",options:["Karena perangkat dinyalakan terus-menerus tanpa dimatikan, menurut kebiasaan orang","Penyimpanan menumpuk, aplikasi jadi lebih berat, baterai melemah, & sistem baru menuntut lebih","Karena perangkat 'lelah' dan perlu diistirahatkan seperti manusia setiap hari"],answer:1,explain:"Kombinasi penyimpanan penuh, perangkat lunak yang makin berat, & baterai tua. Membersihkan & mengelola membantu, meski tidak selamanya.",hint:"Beberapa faktor nyata, atau perangkat 'lelah'?"},
{n:37,type:"tf",micro:"Menutup aplikasi latar",q:"Benar atau Salah: Pada sistem modern, memaksa-tutup semua aplikasi latar terus-menerus selalu mempercepat perangkat tanpa efek samping apa pun.",answer:false,explain:"Sebaliknya, sistem mengelola memori sendiri; aplikasi yang 'diam' di latar hampir tidak memakai sumber daya. Menutup paksa justru memaksanya memuat ulang dari awal, sehingga bisa lebih lambat dibuka lagi.",hint:"Tidak membantu & malah memperlambat buka ulang, atau selalu mempercepat?"},
{n:38,type:"mcq",micro:"Cadangan (backup)",q:"Kenapa penting membuat cadangan data penting (foto, dokumen)?",options:["Perangkat modern menyimpan datanya dengan aman, jadi cadangan hanya membuang ruang penyimpanan","Foto dan dokumen otomatis tersimpan di internet, jadi datamu tetap ada walau perangkat dicuri","Kalau perangkat hilang, rusak, atau dicuri, datamu tidak ikut hilang selamanya"],answer:2,explain:"Perangkat bisa rusak kapan saja. Cadangan ke cloud atau penyimpanan lain adalah jaring pengaman.",hint:"Melindungi dari kehilangan perangkat, atau tidak berguna?"},
{n:39,type:"mcq",micro:"Izin aplikasi",q:"Saat aplikasi meminta izin (lokasi, kontak, kamera, mikrofon), sikap yang bijak:",options:["Berikan hanya yang masuk akal untuk fungsinya; aplikasi senter tidak perlu akses kontak","Berikan semua izin supaya aplikasi bisa bekerja dengan lancar tanpa gangguan","Tolak semua permintaan izin walau aplikasinya sangat berguna bagimu"],answer:0,explain:"Izin yang tidak sesuai fungsi bisa dipakai mengumpulkan data lebih dari perlu. Cocokkan izin dengan kegunaan aplikasi.",hint:"Sesuai fungsi, atau berikan semua?"},
{n:40,type:"open",micro:"Jelaskan alur sebuah aksi",q:"Pilih satu aksi digital sehari-hari (mis. mengirim pesan foto ke teman, membuka peta untuk cari rute, mengunggah tugas ke sistem sekolah). Jelaskan langkah demi langkah apa yang terjadi 'di balik layar': perangkatmu, koneksi, server, dan perangkat/tujuan lain. Sebutkan minimal satu titik di mana koneksi lemah akan terasa.",explain:"Jawaban baik: alur yang menyebut perangkat pengirim → koneksi lokal (Wi-Fi/router) → ISP → server → perangkat penerima, dengan pemahaman bahwa data melewati server perantara (bukan langsung HP ke HP untuk kebanyakan aplikasi), & menunjuk minimal satu tahap yang terpengaruh koneksi lemah.",hint:"Ingat: kebanyakan pesan tidak dikirim langsung HP-ke-HP, melainkan lewat server aplikasi di tengah.",sample:"Aksi: mengirim pesan foto ke teman lewat aplikasi chat. Langkah di balik layar: (1) Aku memilih foto; aplikasi membacanya dari penyimpanan HP-ku. (2) Aplikasi memampatkan foto agar lebih kecil, lalu memecahnya jadi paket-paket data. (3) Paket dikirim dari HP-ku lewat Wi-Fi ke router, lalu ke ISP, lalu ke server aplikasi chat di suatu tempat. (4) Server menerima & menyimpan foto sementara, lalu memberi tahu perangkat temanku bahwa ada pesan baru. (5) Saat HP temanku terhubung internet, ia mengunduh paket-paket foto dari server, menyusunnya kembali, & menampilkannya. Titik di mana koneksi lemah terasa: saat langkah 3, kalau sinyal Wi-Fi/data-ku lemah, unggahan foto akan lambat atau macet & muncul tanda 'mengirim...'; juga di langkah 5, kalau koneksi temanku lemah, foto lama muncul di layarnya meski di layarku sudah 'terkirim'."},
{n:41,type:"mcq",micro:"Mencari informasi",q:"Cara mencari di internet yang lebih efektif:",options:["Ketik pertanyaan sepanjang paragraf penuh supaya mesin pencari paham seluruh ceritamu secara lengkap sekaligus","Pakai kata kunci spesifik & beberapa kata penting, bukan kalimat panjang; saring dengan tanda kutip untuk frasa pasti","Ketik satu kata yang sangat umum saja, sebab hasilnya paling tepat dan sesuai dengan yang kamu cari"],answer:1,explain:"Kata kunci yang tepat mempersempit hasil. Tanda kutip (\"...\") mencari frasa persis; menambah kata kunci menyaring lebih jauh.",hint:"Kata kunci spesifik, atau satu kata umum?"},
{n:42,type:"mcq",micro:"Menilai hasil pencarian",q:"Saat memilih dari hasil pencarian, yang perlu diperhatikan:",options:["Hasil yang muncul paling atas, karena mesin pencari menaruh yang paling benar di urutan pertama","Judul yang paling menarik dan heboh, karena judul seperti itu biasanya ditulis oleh pihak tepercaya","Siapa sumbernya (situs resmi, lembaga, atau blog anonim), kapan ditulis, & apakah ada bukti/rujukan"],answer:2,explain:"Urutan hasil dipengaruhi banyak hal, tidak selalu keakuratan. Nilai sumber, tanggal, & bukti sebelum percaya.",hint:"Sumber, tanggal, bukti, atau yang paling atas / menarik?"},
{n:43,type:"mcq",micro:"Mengunduh dengan aman",q:"Sebelum mengunduh aplikasi atau file:",options:["Unduh dari toko resmi atau situs pembuat aslinya; hindari tautan unduhan dari iklan pop-up atau situs asing","Unduh dari situs mana pun asalkan gratis, termasuk tautan iklan pop-up, karena file yang gratis aman dipakai","Klik tombol 'Download' terbesar yang muncul di halaman, karena tombol yang mencolok biasanya yang asli"],answer:0,explain:"Situs bajakan & iklan sering menyisipkan program berbahaya. Tombol 'Download' besar di halaman asing sering jebakan iklan.",hint:"Sumber resmi, atau mana saja asal gratis?"},
{n:44,type:"mcq",micro:"Mengelola penyimpanan",q:"Cara membebaskan ruang penyimpanan tanpa kehilangan hal penting:",options:["Hapus semua foto dan dokumen tanpa memeriksa lebih dulu, sebab ruang kosong lebih penting daripada isinya","Hapus file unduhan lama, foto ganda, & cache aplikasi; pindahkan foto ke cloud atau kartu memori","Hapus aplikasi sistem satu per satu sampai ruang cukup, karena aplikasi sistem tidak diperlukan oleh perangkat"],answer:1,explain:"Sasar dulu yang jelas aman: unduhan lama, duplikat, cache. Cadangkan sebelum menghapus yang berharga.",hint:"Unduhan lama & cache & pindah ke cloud, atau hapus aplikasi sistem?"},
{n:45,type:"tf",micro:"Restart menyelesaikan banyak masalah",q:"Benar atau Salah: Memulai ulang (restart) perangkat hampir tidak pernah membantu masalah seperti aplikasi macet, Wi-Fi tidak nyambung, atau perangkat lemot sesaat.",answer:false,explain:"Sebaliknya, restart membersihkan memori & menyetel ulang koneksi. Ini langkah pertama yang murah & sering berhasil untuk banyak gangguan.",hint:"Sering membantu, atau tidak pernah?"},
{n:46,type:"mcq",micro:"Wi-Fi tidak nyambung",q:"HP tidak bisa terhubung ke Wi-Fi yang biasanya berfungsi. Langkah pemecahan berurutan yang masuk akal:",options:["Langsung ganti HP dengan yang baru karena masalah jaringan biasanya tanda perangkat sudah rusak parah","Biarkan saja beberapa hari sampai jaringan membaik dengan sendirinya tanpa dicek","Cek mode pesawat mati → lupakan & sambung ulang jaringan → restart HP → restart router → cek apakah perangkat lain bisa"],answer:2,explain:"Mulai dari yang termudah & paling mungkin: pengaturan HP, lalu jaringan, lalu router. Cek perangkat lain memisahkan masalah HP dari masalah jaringan.",hint:"Dari termudah ke jaringan, atau langsung ganti HP?"},
{n:47,type:"mcq",micro:"Perangkat panas",q:"HP terasa sangat panas saat dipakai. Yang sebaiknya dilakukan:",options:["Berhenti sejenak, keluar dari game/kamera berat, lepas dari pengisi daya & sarung tebal, dinginkan di tempat teduh","Masukkan ke kulkas atau freezer sebentar supaya cepat dingin dan siap dipakai lagi untuk bermain","Terus pakai karena panas itu normal dan perangkat modern tahan suhu tinggi"],answer:0,explain:"Panas berlebih bisa merusak baterai & komponen. Kurangi beban & biarkan mendingin alami; jangan didinginkan mendadak (kulkas menyebabkan embun).",hint:"Kurangi beban & dinginkan alami, atau masukkan kulkas?"},
{n:48,type:"mcq",micro:"Aplikasi sering menutup sendiri",q:"Sebuah aplikasi terus 'force close'. Langkah yang bisa dicoba:",options:["Diamkan saja dan jangan lakukan apa-apa, sebab tidak ada langkah yang bisa dicoba untuk memperbaikinya sendiri","Restart HP → perbarui aplikasi → bersihkan cache aplikasi → cek ruang penyimpanan → pasang ulang aplikasi","Hapus semua aplikasi lain di HP dan setel ulang pabrik tanpa mencadangkan data, lalu berharap masalahnya hilang"],answer:1,explain:"Urutan dari yang paling ringan. Cache rusak, versi lama, atau penyimpanan penuh adalah penyebab umum.",hint:"Langkah bertahap dari ringan, atau menyerah?"},
{n:49,type:"mcq",micro:"Menghemat kuota",q:"Cara mengurangi pemakaian data seluler:",options:["Tonton semua video dalam kualitas tertinggi, nyalakan pembaruan otomatis, dan unduh file besar lewat data seluler","Pakai data seluler bahkan saat ada Wi-Fi tersedia, dan biarkan aplikasi mengunduh sendiri di latar belakang","Setel video ke kualitas lebih rendah, matikan pembaruan otomatis di data seluler, unduh saat Wi-Fi untuk dipakai luring"],answer:2,explain:"Video & unduhan besar adalah pemakai kuota terbesar. Menjadwalkannya di Wi-Fi & menurunkan kualitas menghemat banyak.",hint:"Turunkan kualitas & unduh saat Wi-Fi, atau kualitas tertinggi selalu?"},
{n:50,type:"order",micro:"Menyiapkan perangkat baru dengan aman",q:"Urutkan langkah dasar menyiapkan HP baru.",items:["Sambungkan ke Wi-Fi & pasang semua pembaruan sistem yang tersedia","Masuk ke akun & atur kunci layar (PIN/sidik jari/pola)","Pasang hanya aplikasi yang benar-benar dibutuhkan dari toko resmi","Atur cadangan otomatis untuk foto & data penting"],answer:[0,1,2,3],explain:"Perbarui → amankan akses → pasang seperlunya → nyalakan cadangan. Keamanan & pembaruan lebih dulu, aplikasi menyusul.",hint:"Mengatur kunci layar sebelum atau sesudah memperbarui sistem?"},
{n:51,type:"mcq",micro:"Membaca sebelum menyetujui",q:"Saat memasang aplikasi & muncul daftar izin atau persetujuan, kebiasaan yang baik:",options:["Baca sekilas izin yang diminta; kalau ada yang tidak masuk akal untuk fungsinya, batalkan atau cari alternatif","Setujui secepatnya tanpa dibaca, karena aplikasi dari toko resmi tidak mungkin meminta izin yang berlebihan","Tolak setiap aplikasi yang meminta izin, dan kerjakan semua keperluan dengan cara lain di luar aplikasi"],answer:0,explain:"Beberapa detik membaca izin bisa mencegah aplikasi mengakses data yang tidak perlu ia sentuh.",hint:"Baca izin & nilai kewajarannya, atau setujui cepat?"},
{n:52,type:"tf",micro:"Sinyal batang bukan kecepatan",q:"Benar atau Salah: Jumlah 'batang' sinyal yang penuh menjamin internet akan cepat.",answer:false,explain:"Sebaliknya, batang menunjukkan kekuatan sinyal ke menara, bukan kecepatan internet. Menara yang sibuk atau kuota yang diperlambat tetap membuat internet lambat meski sinyal penuh.",hint:"Batang penuh = pasti cepat, atau hanya kekuatan sinyal?"},
{n:53,type:"mcq",micro:"Menyimpan agar bisa dipakai luring",q:"Sebelum bepergian ke daerah tanpa sinyal, persiapan yang berguna:",options:["Tidak perlu persiapan khusus, karena aplikasi di HP tetap berjalan normal walau tanpa sinyal dan unduhan","Unduh peta area itu untuk luring, simpan musik/video/artikel yang mau dipakai, & kabari orang lain rencanamu","Andalkan sinyal yang biasanya tersedia di mana-mana, dan tidak perlu mengabari orang lain soal rencana"],answer:1,explain:"Banyak aplikasi (peta, musik, artikel) punya fitur 'unduh untuk luring'. Menyiapkannya lebih dulu menghindari kebingungan di lokasi.",hint:"Unduh untuk luring lebih dulu, atau andalkan sinyal?"},
{n:54,type:"mcq",micro:"Tethering / hotspot",q:"'Hotspot pribadi' (tethering) berarti...",options:["HP-mu mencuri sinyal Wi-Fi tetangga lalu membagikannya ke perangkat lain di sekitar rumah","Mematikan internet di HP-mu supaya perangkat lain bisa memakai kuota gratis","HP-mu berbagi koneksi data selulernya ke perangkat lain (laptop, HP teman) lewat Wi-Fi/Bluetooth/kabel"],answer:2,explain:"Berguna saat hanya HP-mu yang punya data. Perhatikan kuota, perangkat lain akan memakainya.",hint:"Berbagi koneksi HP ke perangkat lain, atau mencuri Wi-Fi?"},
{n:55,type:"mcq",micro:"Memeriksa keaslian situs",q:"Sebelum memasukkan informasi ke sebuah situs (mis. login), periksa...",options:["Alamatnya dieja benar & sesuai (bukan mirip-mirip), ada 'https', & kamu memang sengaja ke situs itu (bukan dari tautan mencurigakan)","Bahwa tampilan halamannya rapi dan meyakinkan, sebab situs yang dibuat bagus biasanya milik pihak yang tepercaya","Bahwa halaman itu bisa dibuka lancar di browser, sebab situs berbahaya biasanya langsung diblokir otomatis"],answer:0,explain:"Situs palsu sering meniru tampilan & memakai alamat yang mirip (mis. 'g00gle' bukan 'google'). Periksa ejaan alamat.",hint:"Ejaan alamat & https & niat sendiri, atau cukup tampilan bagus?"},
{n:56,type:"tf",micro:"Charger & kabel",q:"Benar atau Salah: Pengisi daya & kabel yang rusak atau tidak sesuai tidak masalah dipakai terus karena tidak berpengaruh pada baterai atau keselamatan.",answer:false,explain:"Sebaliknya, charger abal-abal atau kabel terkelupas bisa memberi tegangan tidak stabil, memanaskan, merusak baterai, & dalam kasus buruk menimbulkan percikan. Pakai yang layak & sesuai.",hint:"Bisa merusak & berbahaya, atau tidak berpengaruh?"},
{n:57,type:"mcq",micro:"Menonaktifkan yang tidak dipakai",q:"Mematikan Bluetooth, lokasi, & Wi-Fi saat benar-benar tidak dipakai...",options:["Tidak ada gunanya, fitur itu hanya membuat perangkat lebih rapi","Menghemat baterai & sedikit mengurangi permukaan yang bisa diserang","Membuat HP rusak karena sensor dan sambungan jadi tidak terpakai lama"],answer:1,explain:"Radio yang aktif terus memakai daya & selalu 'mendengarkan'. Menyalakannya hanya saat perlu adalah kebiasaan hemat & aman.",hint:"Hemat baterai & lebih aman, atau merusak HP?"},
{n:58,type:"mcq",micro:"Membedakan masalah perangkat vs layanan",q:"Sebuah aplikasi tidak bisa memuat konten. Cara mengecek apakah masalahnya di HP-mu atau di layanannya:",options:["Langsung simpulkan bahwa HP-mu rusak, lalu segera ganti dengan HP baru tanpa mengecek hal lain dulu","Langsung simpulkan bahwa internet sedang mati di seluruh kota, tanpa mencoba aplikasi lain atau bertanya pada teman","Coba aplikasi/situs lain (jalan? berarti internetmu oke), cek apakah teman mengalami hal sama, cek status layanan bila ada"],answer:2,explain:"Menguji satu variabel: kalau situs lain jalan, internetmu oke & masalahnya di layanan itu. Kalau teman juga kena, kemungkinan besar layanannya yang bermasalah.",hint:"Uji dengan aplikasi lain & tanya teman, atau langsung menyimpulkan?"},
{n:59,type:"mcq",micro:"Reset sebagai langkah terakhir",q:"'Setel ulang ke setelan pabrik' (factory reset) sebaiknya...",options:["Jadi langkah terakhir setelah cara lain gagal, & hanya setelah mencadangkan data karena semua data di perangkat akan terhapus","Dilakukan rutin tiap minggu agar HP tetap bersih, dan data aman karena tersimpan kembali secara otomatis","Menjadi langkah pertama saat muncul masalah kecil, sebelum mencoba menutup aplikasi atau memulai ulang perangkat"],answer:0,explain:"Factory reset menghapus semuanya. Berguna untuk masalah berat atau sebelum menjual perangkat, tapi cadangkan dulu.",hint:"Langkah terakhir + cadangkan dulu, atau rutin mingguan?"},
{n:60,type:"open",micro:"Panduan pemecahan masalah",q:"Buat panduan singkat 'langkah pertama saat perangkat bermasalah' untuk dipakai adikmu. Sertakan minimal 4 masalah umum (mis. internet lambat, aplikasi macet, penyimpanan penuh, baterai boros) dan untuk masing-masing 2-3 langkah berurutan yang aman dicoba sendiri, plus satu tanda kapan harus minta bantuan orang dewasa.",explain:"Jawaban baik: minimal 4 masalah umum, masing-masing dengan 2-3 langkah berurutan yang aman & benar (dari ringan ke lebih dalam), peringatan untuk tidak menghapus hal yang tidak dikenali, & tanda-tanda bahaya konkret yang mengharuskan minta bantuan dewasa (tidak menyala, menggembung, panas ekstrem, permintaan pembayaran asing).",hint:"Susun tiap masalah dari langkah paling ringan (restart) ke lebih dalam, & selalu sertakan 'apa yang JANGAN dilakukan sendiri'.",sample:"Panduan Pertolongan Pertama Perangkat: 1. INTERNET LAMBAT/PUTUS: (a) cek mode pesawat tidak menyala; (b) matikan lalu nyalakan Wi-Fi, atau restart HP; (c) coba buka situs lain, kalau semua lambat & orang lain di rumah juga, tunggu atau beri tahu orang dewasa; kalau hanya HP-mu, lupakan jaringan Wi-Fi lalu sambungkan ulang. 2. APLIKASI MACET / MENUTUP SENDIRI: (a) tutup aplikasi lalu buka lagi; (b) restart HP; (c) buka toko aplikasi & perbarui aplikasi itu. Kalau setelah semua ini masih terus menutup & itu aplikasi penting (mis. untuk tugas sekolah), minta bantuan orang dewasa. 3. PENYIMPANAN PENUH: (a) buka Pengaturan > Penyimpanan untuk lihat apa yang paling banyak; (b) hapus file di folder Unduhan yang sudah tidak dipakai & foto/video yang ganda; (c) bersihkan cache aplikasi besar. JANGAN hapus aplikasi atau file yang kamu tidak tahu fungsinya, tanya dulu. 4. BATERAI CEPAT HABIS: (a) turunkan kecerahan layar & nyalakan mode hemat daya; (b) cek aplikasi mana yang paling boros di Pengaturan > Baterai & tutup yang tidak dipakai; (c) matikan lokasi/Bluetooth saat tidak perlu. Kalau baterai tiba-tiba habis sangat cepat dalam sehari padahal biasanya awet, atau HP menggembung/sangat panas, segera beri tahu orang dewasa & jangan diisi daya dulu. KAPAN SELALU MINTA BANTUAN DEWASA: HP tidak mau menyala sama sekali, layar retak, HP menggembung atau berbau terbakar, atau muncul permintaan memasukkan kata sandi/pembayaran yang tidak kamu kenali."},
{n:61,type:"mcq",micro:"Ketergantungan pada satu perangkat",q:"Menyimpan semua hal penting (foto, dokumen, kata sandi, kontak) hanya di satu perangkat tanpa cadangan berisiko karena...",options:["Perangkat lain menyalin isinya otomatis, jadi data tetap ada walau perangkat rusak","Kalau perangkat itu hilang/rusak/dicuri, semuanya hilang sekaligus & sulit dipulihkan","Perangkat modern jarang rusak atau hilang dalam beberapa tahun, jadi risikonya kecil dan bisa diabaikan"],answer:1,explain:"Satu titik kegagalan. Cadangan ke cloud atau media lain menyebar risiko sehingga kehilangan perangkat tidak berarti kehilangan data.",hint:"Semua bisa hilang sekaligus, atau perangkat tidak pernah rusak?"},
{n:62,type:"mcq",micro:"Gratis sering berarti kamu produknya",q:"Banyak aplikasi & layanan 'gratis' membiayai diri dengan...",options:["Sumbangan sukarela dari para pemakai, sehingga perusahaan tidak perlu iklan atau data","Dana dari pemerintah untuk aplikasi gratis, jadi perusahaannya tidak butuh pemasukan dari pemakai","Menampilkan iklan & mengumpulkan data pemakaian untuk ditargetkan atau dijual"],answer:2,explain:"'Kalau kamu tidak membayar produk, sering kamu-lah produknya.' Memahami ini membantu menilai apa yang kamu tukar untuk 'gratis'.",hint:"Iklan & data, atau benar-benar tanpa biaya bagi siapa pun?"},
{n:63,type:"tf",micro:"Menghapus bukan berarti hilang total",q:"Benar atau Salah: File yang 'dihapus' dari perangkat kadang masih bisa dipulihkan sampai ruangnya ditimpa data baru, & data yang pernah diunggah ke internet bisa saja tersimpan di banyak tempat.",answer:true,explain:"Penghapusan biasa hanya menandai ruang sebagai 'bisa dipakai lagi'. Dan apa pun yang sudah tersebar online sulit ditarik kembali sepenuhnya.",hint:"Bisa tertinggal jejak, atau hilang seketika & sempurna?"},
{n:64,type:"mcq",micro:"Memilih menyimpan di cloud atau lokal",q:"Menyimpan di cloud vs hanya di perangkat, pertimbangannya:",options:["Cloud: bisa diakses dari mana saja & aman dari kehilangan perangkat, tapi butuh internet & kamu mempercayakan data ke penyedia. Lokal: kendali penuh & luring, tapi rawan hilang bila perangkat rusak","Cloud lebih unggul dari sisi kemudahan dan keamanan data, tanpa kekurangan berarti, sehingga penyimpanan lokal sebaiknya ditinggalkan karena rawan rusak dan sulit dibagikan","Lokal lebih baik karena kendali penuh dan bisa dipakai luring, sedangkan cloud tidak berguna karena datamu bisa dibaca penyedia tanpa batas dan sering hilang"],answer:0,explain:"Keduanya punya kelebihan & risiko. Banyak orang memakai keduanya: cloud untuk cadangan & akses, lokal untuk yang sangat pribadi.",hint:"Masing-masing punya kelebihan & risiko, atau salah satu selalu menang?"},
{n:65,type:"mcq",micro:"Internet tidak melupakan",q:"Sebelum mengunggah sesuatu (komentar, foto, video), pemikiran yang bijak:",options:["'Kalau kuhapus nanti, tak ada yang sempat menyimpan atau memotret layarnya'","'Apakah aku nyaman ini dilihat orang lain, termasuk di masa depan, meski nanti kuhapus?'","'Yang penting teman dekatku suka dan memberi banyak like, jadi isinya tidak perlu dipikirkan lagi'"],answer:1,explain:"Unggahan bisa disalin, dibagikan, & diarsipkan orang lain sebelum kamu menghapusnya. Anggap segala yang diunggah bisa permanen.",hint:"Anggap bisa permanen, atau bisa dihapus tanpa jejak?"},
{n:66,type:"mcq",micro:"Baterai: mitos & fakta",q:"Untuk baterai lithium HP modern, kebiasaan yang umumnya lebih baik:",options:["Tunggu baterai habis di 0% lebih dulu baru diisi, dan biarkan HP terus menyala saat panas","Isi daya semalaman tiap malam dengan HP ditutup bantal supaya hangat dan baterainya lebih awet","Isi daya kapan saja nyaman & hindari sering membiarkannya benar-benar habis (0%) atau selalu panas"],answer:2,explain:"Baterai modern tidak butuh 'dikuras habis'. Yang membuatnya cepat aus: sering ke 0%, panas berlebih, & selalu di 100% sambil panas.",hint:"Isi kapan saja & hindari 0% + panas, atau selalu tunggu 0%?"},
{n:67,type:"mcq",micro:"Perangkat lama masih berguna",q:"HP lama yang sudah tidak dipakai sebagai telepon utama masih bisa berguna untuk...",options:["Jam alarm, pemutar musik luring, kamera cadangan, perangkat baca, atau diberikan/didaur ulang dengan benar","Tidak berguna lagi, jadi langsung buang ke tempat sampah biasa bersama sampah rumah tangga lainnya","Dipajang di lemari sebagai hiasan, karena HP lama tidak mungkin menjalankan fungsi lain lagi"],answer:0,explain:"Perangkat elektronik mengandung bahan berharga & berbahaya. Memakainya lagi atau mendaur ulangnya (bukan sampah biasa) lebih bertanggung jawab.",hint:"Bisa dipakai ulang / didaur ulang, atau buang ke sampah biasa?"},
{n:68,type:"tf",micro:"Pembaruan bisa mengubah",q:"Benar atau Salah: Pembaruan perangkat lunak kadang mengubah tampilan atau menghapus fitur, selain memperbaiki keamanan, jadi wajar sesekali membaca catatan pembaruannya.",answer:true,explain:"Sebagian besar pembaruan bermanfaat & penting untuk keamanan, tapi membaca 'apa yang baru' membantu kamu tidak terkejut oleh perubahan.",hint:"Bisa mengubah tampilan/fitur juga, atau selalu hanya perbaikan?"},
{n:69,type:"mcq",micro:"Jejak yang ditinggalkan browsing",q:"Saat menjelajah web, jejak yang biasanya tertinggal:",options:["Hanya di HP-mu sendiri, sehingga situs yang kamu kunjungi dan penyedia internetmu tidak menyimpan catatan","Riwayat di perangkatmu, cookie di browser, catatan di ISP, & log di situs yang kamu kunjungi","Jejaknya hilang begitu halaman ditutup, jadi tak ada catatan di mana-mana"],answer:1,explain:"Aktivitas online meninggalkan jejak di beberapa lapisan. Mode 'penyamaran' hanya menyembunyikan riwayat lokal, bukan yang lain.",hint:"Beberapa lapisan jejak, atau tidak ada jejak?"},
{n:70,type:"mcq",micro:"Menilai klaim teknis",q:"Sebuah video mengklaim 'trik rahasia agar HP 10x lebih cepat'. Sikap kritis:",options:["Langsung ikuti semua langkahnya persis seperti di video, termasuk memasang aplikasi asing dan mengubah semua setelan yang disebut","Bagikan ke semua teman tanpa mencoba atau memeriksa dulu, supaya mereka juga ikut mendapatkan trik rahasia yang katanya ajaib itu","Curiga: cari sumber tepercaya, waspadai yang menyuruh memasang aplikasi asing atau mengubah setelan yang tidak dipahami"],answer:2,explain:"Banyak 'trik' begini tidak berguna atau berbahaya (memasang aplikasi pembersih penuh iklan, mengubah setelan sistem). Verifikasi dulu.",hint:"Curiga & verifikasi, atau langsung ikuti / sebar?"},
{n:71,type:"mcq",micro:"Berbagi perangkat",q:"Saat memakai komputer/HP bersama (di sekolah, warnet, keluarga), kebiasaan yang aman:",options:["Keluar (logout) dari akun setelah selesai, jangan menyimpan kata sandi di perangkat itu, & hapus riwayat bila perlu","Tetap login supaya cepat dipakai lain kali, dan biarkan browser menyimpan kata sandi serta riwayat","Simpan semua kata sandi di perangkat itu supaya tak perlu mengetik ulang, karena perangkat bersama aman dari orang lain"],answer:0,explain:"Perangkat bersama berarti orang lain bisa memakai akunmu bila kamu lupa keluar. Logout adalah kebiasaan dasar.",hint:"Logout & jangan simpan sandi, atau tetap login?"},
{n:72,type:"mcq",micro:"Memahami sebelum mengubah setelan",q:"Sebelum mengubah setelan sistem yang tidak kamu pahami (mis. 'opsi pengembang', DNS, izin khusus):",options:["Ubah semua setelan ke nilai tertinggi supaya perangkat menjadi paling cepat, tanpa perlu tahu fungsinya dan tanpa mencatat setelan awalnya","Cari tahu dulu apa fungsinya & risikonya, atau tanya orang yang paham; catat setelan awal supaya bisa dikembalikan","Ubah saja dulu lalu lihat apa yang terjadi, karena kalau ada kesalahan bisa dikembalikan sendiri tanpa dicatat"],answer:1,explain:"Setelan sistem bisa membuat perangkat tidak stabil atau kurang aman bila diubah tanpa paham. Pahami & catat sebelum mengubah.",hint:"Pahami & catat dulu, atau ubah & lihat saja?"},
{n:73,type:"tf",micro:"Koneksi cepat tidak menjamin aman",q:"Benar atau Salah: Koneksi internet yang cepat & stabil tidak dengan sendirinya berarti aman dari penyadapan atau situs berbahaya.",answer:true,explain:"Kecepatan & keamanan adalah dua hal berbeda. Wi-Fi publik bisa cepat tapi tidak aman; situs berbahaya bisa dibuka lewat koneksi cepat.",hint:"Cepat = aman, atau dua hal berbeda?"},
{n:74,type:"mcq",micro:"Ketika perangkat menyarankan sesuatu",q:"Perangkat menampilkan 'Simpan kata sandi ini?' atau 'Izinkan lokasi selalu?'. Sikap yang baik:",options:["Pilih opsi yang paling nyaman setiap saat tanpa memikirkan konteks, karena kenyamanan lebih penting daripada risiko","Tolak semuanya tanpa berpikir dan tanpa melihat konteks, sehingga banyak aplikasi berguna jadi tidak berfungsi","Pertimbangkan tiap kali sesuai konteks; 'selalu' & 'simpan' nyaman tapi menambah risiko bila perangkat dipakai orang lain atau hilang"],answer:2,explain:"Kenyamanan & keamanan sering bertukar. Keputusan yang sadar per situasi lebih baik daripada kebiasaan otomatis ke salah satu.",hint:"Pertimbangkan per konteks, atau selalu satu pilihan?"},
{n:75,type:"order",micro:"Menyelidiki 'internet lambat'",q:"Urutkan langkah menyelidiki kenapa internet di rumah lambat malam ini.",items:["Cek apakah hanya satu perangkat atau semua perangkat yang lambat","Cek berapa banyak yang sedang dipakai bersamaan (streaming, unduh besar)","Restart router & tunggu sekitar 2 menit","Kalau tetap lambat di semua perangkat & tidak ada pemakaian berat, catat waktunya & laporkan ke penyedia layanan"],answer:[0,1,2,3],explain:"Satu atau semua perangkat → beban jaringan → restart router → lapor bila di luar kendalimu. Menyempit dari perangkat ke jaringan ke penyedia.",hint:"Mengecek jumlah perangkat terpengaruh sebelum atau sesudah restart router?"},
{n:76,type:"tf",micro:"Perangkat bisa terinfeksi tanpa mengunduh 'file'",q:"Benar atau Salah: Perangkat bisa terkena masalah keamanan hanya dari membuka tautan berbahaya atau memasang aplikasi tidak resmi, tidak harus dari 'mengunduh virus' secara sadar.",answer:true,explain:"Banyak masalah datang dari aplikasi tidak resmi, izin berlebihan, atau tautan yang mengarah ke halaman jebakan. Berhati-hati pada tautan & sumber aplikasi penting.",hint:"Bisa lewat tautan & aplikasi tidak resmi, atau hanya lewat unduhan sadar?"},
{n:77,type:"mcq",micro:"Menimbang aplikasi baru",q:"Sebelum memasang aplikasi baru, pertanyaan yang berguna:",options:["'Apakah aku benar-benar butuh ini? Siapa pembuatnya? Izin apa yang diminta? Bagaimana ulasan & jumlah pemasangannya?'","'Apakah ikonnya bagus dan warnanya menarik? Kalau ya, langsung pasang tanpa memeriksa pembuat, izin, atau ulasan'","'Apakah temanku juga memakainya?' saja, tanpa perlu bertanya soal kebutuhan, pembuat, izin yang diminta, atau ulasan dari pengguna lainnya"],answer:0,explain:"Menilai kebutuhan, pembuat, izin, & reputasi mengurangi risiko memasang aplikasi yang sia-sia atau berbahaya.",hint:"Kebutuhan + pembuat + izin + reputasi, atau ikon bagus?"},
{n:78,type:"mcq",micro:"Perangkat & waktu",q:"Menyadari berapa lama & untuk apa kamu memakai perangkat berguna karena...",options:["Hanya penting bagi orang dewasa, sedangkan anak dan remaja belum perlu memperhatikan waktu pemakaiannya","Membantu kamu memilih dengan sadar, memastikan waktu untuk tidur, gerak, & hubungan tatap muka tetap cukup","Tidak berguna, karena lamanya pemakaian ditentukan oleh aplikasinya dan tidak bisa diubah oleh pemakai"],answer:1,explain:"Fitur 'waktu layar' menunjukkan pola pemakaian. Kesadaran adalah langkah pertama untuk menyeimbangkannya (dibahas lebih dalam di keterampilan lain).",hint:"Membantu memilih dengan sadar, atau tidak bisa diubah?"},
{n:79,type:"mcq",micro:"Perangkat sebagai alat, bukan tujuan",q:"Cara pandang yang sehat terhadap perangkat & internet:",options:["Sesuatu yang harus dipegang setiap saat, termasuk saat makan, tidur, dan berbincang dengan orang lain","Sesuatu yang berbahaya dan sebaiknya dijauhi sepenuhnya, karena manfaatnya untuk belajar tidak sebanding","Alat yang sangat berguna untuk belajar, terhubung, & berkarya, yang kita kendalikan, bukan sebaliknya"],answer:2,explain:"Perangkat memperluas kemampuan kita. Tujuannya melayani hidup kita, jadi kitalah yang mengatur kapan & bagaimana memakainya.",hint:"Alat yang kita kendalikan, atau selalu di tangan / dihindari total?"},
{n:80,type:"open",micro:"Menilai sebuah keputusan digital",q:"Temanmu ingin memasang aplikasi 'pembersih & pempercepat HP' yang iklannya muncul terus-menerus & mengklaim membuat HP 3x lebih cepat. Analisis: (a) apa yang perlu dicek sebelum memasangnya, (b) kemungkinan apa yang sebenarnya dilakukan aplikasi seperti ini, (c) cara-cara nyata mempercepat HP yang lambat, (d) saran akhirmu untuk temanmu.",explain:"Jawaban baik: menyebut hal-hal konkret yang perlu dicek (pembuat, izin, iklan, bukti klaim), menjelaskan bahwa aplikasi 'pembersih' sering kontraproduktif & kenapa, memberi daftar cara nyata mempercepat HP yang berbasis pengaturan bawaan, & saran akhir yang jelas (jangan pasang) dengan alternatif yang bisa dilakukan.",hint:"Kunci: sistem modern mengelola memori & cache sendiri; 'pembersih' pihak ketiga sering menambah iklan & beban alih-alih membantu.",sample:"(a) Yang perlu dicek: siapa pembuatnya & apakah dikenal, izin apa yang diminta (aplikasi pembersih sering minta akses berlebihan), berapa banyak iklan & apakah ada biaya tersembunyi, ulasan yang jujur (bukan hanya bintang 5 tanpa isi), & apakah 'klaim 3x lebih cepat' didukung bukti (biasanya tidak). (b) Kemungkinan yang sebenarnya terjadi: aplikasi begini sering hanya menutup aplikasi latar (yang akan terbuka lagi & malah memperlambat), membersihkan cache (yang sistem sudah kelola sendiri), sambil menampilkan banyak iklan, memakai baterai & data untuk iklan itu, meminta izin luas, & kadang menampilkan 'peringatan palsu' agar kita terus memakainya. Jadi sering justru menambah beban, bukan mengurangi. (c) Cara nyata mempercepat HP lambat: bebaskan penyimpanan (hapus unduhan lama, foto ganda, cache aplikasi besar lewat Pengaturan bawaan), copot aplikasi yang tidak dipakai, perbarui sistem & aplikasi, restart HP secara berkala, kurangi widget & animasi bila ada opsinya, dan kalau HP sudah sangat tua, terima bahwa sebagian keterbatasan berasal dari perangkat kerasnya. (d) Saranku: jangan pasang aplikasi 'pembersih' itu. Coba dulu langkah bawaan, terutama membebaskan penyimpanan & memperbarui, karena itu penyebab paling umum HP lambat. Kalau masih lambat, kita cek bersama aplikasi mana yang paling berat di Pengaturan > Baterai/Penyimpanan."},
{n:81,type:"mcq",micro:"Skenario: HP hilang",q:"HP-mu hilang di luar rumah. Langkah pertama yang tepat (dari perangkat lain):",options:["Buka fitur 'temukan perangkatku' dari akunmu untuk melacak/mengunci/menghapus dari jauh, & ganti kata sandi akun-akun penting","Tidak melakukan apa-apa dan hanya berharap HP-nya ditemukan sendiri oleh orang baik, tanpa melacak, mengunci, atau mengganti kata sandi akunmu","Mengumumkan nomor HP dan alamat rumahmu di media sosial supaya orang yang menemukannya bisa mengantarkannya ke rumahmu"],answer:0,explain:"Fitur pelacak bisa mengunci perangkat & melindungi data. Mengganti kata sandi mencegah akses ke akun bila perangkat dibuka.",hint:"Lacak/kunci dari jauh & ganti sandi, atau diam / umumkan data pribadi?"},
{n:82,type:"mcq",micro:"Skenario: penyimpanan penuh saat butuh memotret",q:"Kamu ingin memotret momen penting tapi muncul 'penyimpanan penuh'. Solusi cepat yang aman:",options:["Restart berulang kali sampai ruang penyimpanan muncul dengan sendirinya, sambil terus mencoba memotret","Hapus beberapa video lama atau file di folder Unduhan, atau turunkan resolusi foto sementara","Hapus aplikasi yang tidak dikenali di layar tanpa memeriksa isinya, termasuk yang berisi tugas sekolah"],answer:1,explain:"Video & unduhan lama biasanya paling besar. Menghapus beberapa dengan cepat, atau menurunkan resolusi, membebaskan ruang untuk memotret sekarang.",hint:"Hapus video/unduhan lama atau turunkan resolusi, atau hapus aplikasi acak?"},
{n:83,type:"mcq",micro:"Skenario: minta bantuan yang jelas",q:"Kamu minta bantuan soal masalah perangkat. Cara menjelaskan yang membantu penolong:",options:["Cukup bilang 'HP-ku rusak, tolong betulkan', karena penolong bisa menebak sendiri dari tampilan perangkat","Serahkan HP begitu saja tanpa cerita, supaya penolong mencari tahu sendiri tanpa dipengaruhi penjelasanmu","Sebutkan: apa yang terjadi persis, kapan mulai, apa yang sudah kamu coba, & pesan error yang muncul (foto bila ada)"],answer:2,explain:"Deskripsi yang spesifik + langkah yang sudah dicoba menghemat waktu penolong & meningkatkan peluang masalah cepat teratasi.",hint:"Detail + yang sudah dicoba + error, atau 'rusak, tolong'?"},
{n:84,type:"mcq",micro:"Skenario: sekolah minta pasang aplikasi",q:"Sekolah meminta memasang aplikasi tertentu untuk tugas. Sikap yang seimbang:",options:["Pasang dari toko resmi, cek izin yang diminta, & tanyakan ke guru bila ada izin yang terasa berlebihan untuk fungsinya","Tolak permintaan sekolah karena aplikasi dari sekolah berbahaya, lalu kerjakan tugas dengan caramu sendiri","Pasang dari sumber mana pun yang cepat, lalu setujui semua izin karena sekolah yang memintanya"],answer:0,explain:"Permintaan resmi tetap layak diperiksa. Memasang dari sumber resmi & menanyakan izin yang janggal adalah kehati-hatian yang wajar, bukan penolakan.",hint:"Pasang dari sumber resmi + periksa izin + tanya bila janggal, atau tolak / pasang buta?"},
{n:85,type:"tf",micro:"Belajar dasar itu memberdayakan",q:"Benar atau Salah: Memahami dasar cara kerja perangkat & internet membuat kita lebih mampu memecahkan masalah sendiri, membuat pilihan yang aman, & tidak mudah tertipu klaim palsu.",answer:true,explain:"Pengetahuan dasar mengubah kita dari 'pemakai yang bingung & bergantung' jadi 'pemakai yang berdaya'. Itu tujuan literasi digital.",hint:"Memberdayakan, atau tidak berpengaruh?"},
{n:86,type:"mcq",micro:"Skenario: koneksi buruk saat ujian daring",q:"Saat ujian atau tugas daring, koneksimu tidak stabil. Persiapan & tindakan yang bijak:",options:["Menyalahkan diri sendiri, menyerah begitu saja, lalu tidak mengatakan apa-apa kepada guru, karena koneksi yang tak stabil dianggap kesalahanmu sendiri","Sebelumnya: tes koneksi, siapkan cadangan (hotspot/lokasi lain), simpan pekerjaan sering. Saat terjadi: tetap tenang, pindah ke koneksi cadangan, & segera kabari guru dengan bukti (tangkapan layar)","Panik, menutup semua jendela dan aplikasi sekaligus, lalu mengulang dari awal tanpa menyimpan pekerjaan dan tanpa mengabari guru, berharap koneksi pulih sendiri nanti"],answer:1,explain:"Masalah koneksi sebagian bisa diantisipasi (cadangan, menyimpan sering) & sebagian perlu komunikasi cepat + bukti ke pihak yang menilai.",hint:"Siapkan cadangan & kabari dengan bukti, atau panik / menyerah?"},
{n:87,type:"mcq",micro:"Skenario: perangkat keluarga bersama",q:"Keluargamu berbagi satu tablet. Cara menjaganya tetap tertib & aman:",options:["Pakai satu akun bersama untuk semua anggota keluarga tanpa kunci layar, agar mudah dipakai bergantian dan data pribadi disimpan di sana","Simpan tablet di tempat tersembunyi supaya tidak dipakai, sehingga aturan pemakaian dan pengaturan akun tidak diperlukan","Buat profil/akun terpisah bila memungkinkan, sepakati aturan pemakaian & penyimpanan, & jaga kunci layar; jangan menyimpan data sangat pribadi di sana"],answer:2,explain:"Perangkat bersama butuh kesepakatan & pemisahan. Profil terpisah menjaga data & pengaturan tiap orang; kunci layar melindungi dari akses luar.",hint:"Profil terpisah + aturan + kunci layar, atau satu akun untuk semua?"},
{n:88,type:"mcq",micro:"Skenario: iklan menyerupai sistem",q:"Saat browsing muncul kotak 'PERINGATAN! Perangkat Anda terinfeksi 5 virus! Bersihkan sekarang!'. Ini biasanya...",options:["Iklan/penipuan, bukan pesan asli dari sistemmu; tutup tab itu & jangan klik apa pun di dalamnya","Peringatan resmi dari sistemmu, jadi klik 'Bersihkan sekarang' dan pasang aplikasi yang disarankan","Tanda HP-mu sudah terinfeksi, jadi sebarkan peringatan itu ke teman dan ikuti semua instruksinya"],answer:0,explain:"Halaman web tidak bisa memindai perangkatmu. Pesan menakutkan begini adalah taktik menakut-nakuti agar kamu memasang aplikasi berbahaya atau membayar.",hint:"Penipuan iklan, atau peringatan resmi?"},
{n:89,type:"mcq",micro:"Skenario: menjelaskan ke orang lain",q:"Kakekmu bingung memakai HP barunya. Cara membantu yang memberdayakan:",options:["Bilang 'gampang kok' lalu tinggalkan ia sendiri, karena orang tua biasanya bisa belajar sendiri","Tunjukkan langkah demi langkah sambil ia yang melakukannya, buat catatan sederhana, & ulangi beberapa kali dengan sabar","Ambil alih HP-nya dan kerjakan sendiri dengan cepat, supaya ia tidak perlu belajar dan mencoba sendiri"],answer:1,explain:"Membantu orang belajar (ia yang melakukan, kamu memandu) lebih berharga daripada melakukannya untuknya. Catatan membantu ia mandiri.",hint:"Pandu ia melakukan sendiri + catatan, atau ambil alih / abaikan?"},
{n:90,type:"order",micro:"Proyek: audit perangkat pribadi",q:"Urutkan langkah 'audit' sederhana perangkatmu sekali sebulan.",items:["Cek penyimpanan: hapus unduhan lama, duplikat, & cache besar","Cek aplikasi: copot yang tidak dipakai 1 bulan terakhir","Cek izin & notifikasi: cabut izin yang tidak sesuai fungsi, matikan notifikasi yang mengganggu","Pastikan sistem & aplikasi penting diperbarui, & cadangan berjalan"],answer:[0,1,2,3],explain:"Bersihkan penyimpanan → rapikan aplikasi → tinjau izin & notifikasi → perbarui & cadangkan. Rutin bulanan menjaga perangkat ringan, aman, & tenang.",hint:"Meninjau izin sebelum atau sesudah mencopot aplikasi yang tidak dipakai?"},
{n:91,type:"mcq",micro:"Skenario: tergoda Wi-Fi 'gratis' tak dikenal",q:"Di tempat umum muncul Wi-Fi bernama 'Free_WiFi_Fast' tanpa kata sandi. Sikap yang aman:",options:["Sambungkan dan pakai seperti biasa, termasuk login dan mengisi data pribadi, karena Wi-Fi gratis dibuat tulus oleh pengelola tempat","Sambungkan lalu buka aplikasi bank untuk cek saldo dan transfer, karena jaringan tanpa kata sandi lebih cepat dari data seluler","Berhati-hati: jaringan tak dikenal bisa dibuat untuk menyadap; kalau terpaksa pakai, hindari login/hal sensitif & lebih baik pakai data seluler untuk itu"],answer:2,explain:"Jaringan terbuka tak dikenal berisiko. Untuk sekadar melihat peta mungkin cukup aman; untuk login atau data pribadi, jangan lewat jaringan seperti itu.",hint:"Hati-hati & hindari hal sensitif, atau pakai bebas termasuk bank?"},
{n:92,type:"tf",micro:"Tidak semua masalah bisa diselesaikan sendiri",q:"Benar atau Salah: Sebagian masalah perangkat (kerusakan fisik, baterai menggembung, masalah yang menyangkut biaya atau akun keluarga) sebaiknya ditangani dengan bantuan orang dewasa atau teknisi, bukan dicoba-coba sendiri.",answer:true,explain:"Mengetahui batas 'yang aman kucoba sendiri' vs 'perlu bantuan' adalah bagian dari keterampilan, terutama untuk hal yang menyangkut keselamatan atau uang.",hint:"Sebagian perlu bantuan, atau semua harus diselesaikan sendiri?"},
{n:93,type:"mcq",micro:"Skenario: perangkat minta pembaruan besar saat sibuk",q:"Perangkat menawarkan pembaruan sistem besar, tapi kamu sedang butuh perangkat & baterai 30%. Pilihan bijak:",options:["Tunda & jadwalkan pembaruan untuk saat perangkat diisi daya, terhubung Wi-Fi, & tidak sedang dibutuhkan (mis. malam hari)","Abaikan pembaruan itu untuk seterusnya, karena pembaruan sistem mengganggu dan jarang memperbaiki masalah keamanan","Perbarui sekarang juga di tengah pekerjaan penting, walau baterai tinggal 30%, supaya cepat selesai"],answer:0,explain:"Pembaruan penting tapi tidak harus sekarang juga. Menunda ke waktu yang aman (daya cukup, Wi-Fi, tidak sibuk) menghindari gangguan.",hint:"Jadwalkan ke waktu aman, atau abaikan selamanya / paksa sekarang?"},
{n:94,type:"mcq",micro:"Skenario: menilai 'HP baru wajib'",q:"Iklan meyakinkanmu bahwa HP-mu 'sudah ketinggalan' & kamu harus ganti. Cara berpikir yang jernih:",options:["Tidak perlu mengganti HP walau sudah rusak parah, tidak lagi menjalankan aplikasi yang dibutuhkan, dan berhenti mendapat pembaruan keamanan dari pembuatnya sampai kapan pun","Tanya: apakah HP-ku masih menjalankan yang kubutuhkan? Apakah masih dapat pembaruan keamanan? Kalau ya, mengganti belum tentu perlu, & membeli terlalu sering membebani kantong & lingkungan","Beli yang terbaru begitu keluar, karena iklan benar bahwa HP lama ketinggalan, tanpa perlu menimbang kebutuhan, kondisi HP, atau keuangan keluarga"],answer:1,explain:"Kebutuhan nyata (fungsi + keamanan) adalah ukuran yang lebih baik daripada iklan. Perangkat yang masih memadai layak dipakai terus.",hint:"Nilai dari fungsi & pembaruan keamanan, atau ikut iklan?"},
{n:95,type:"tf",micro:"Literasi perangkat itu keterampilan hidup",q:"Benar atau Salah: Kemampuan memakai, merawat, & memecahkan masalah perangkat & internet adalah keterampilan hidup yang berguna di sekolah, pekerjaan, & urusan sehari-hari.",answer:true,explain:"Hampir semua bidang kini melibatkan perangkat digital. Menguasai dasarnya membuat kita lebih mandiri & efektif di banyak hal.",hint:"Keterampilan hidup yang luas, atau hanya untuk sebagian orang?"},
{n:96,type:"mcq",micro:"Skenario: perangkat teman terkunci pola",q:"Teman lupa pola/PIN HP-nya & minta bantuanmu. Yang tepat:",options:["Coba tebak pola atau PIN berkali-kali sampai terbuka, karena lambat laun ketemu dan itu tidak berdampak pada data, akun, atau perangkat temanmu yang sedang kamu bantu","Cari cara membobol HP dari internet dan ikuti langkahnya, karena trik membuka paksa itu legal dan tidak menghapus data di dalamnya","Sarankan cara resmi pemulihan lewat akunnya, atau bantuan pusat layanan; jangan coba menebak berkali-kali atau memakai 'trik' membuka paksa yang bisa menghapus data atau ilegal"],answer:2,explain:"Jalur resmi (akun pemulihan, pusat layanan dengan bukti kepemilikan) aman & sah. Membobol paksa berisiko menghapus data & bisa melanggar aturan.",hint:"Jalur resmi pemulihan, atau menebak / membobol?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu makin melek perangkat & internet:",options:["Kamu bisa menjelaskan bedanya Wi-Fi & data, memecahkan masalah umum sendiri secara bertahap, menilai aplikasi sebelum memasang, & tahu kapan minta bantuan","Kamu hafal semua istilah teknis, tetapi panik setiap kali ada masalah kecil, tidak bisa menjelaskan bedanya Wi-Fi dan data, dan tidak tahu harus bertanya kepada siapa","Kamu menyerahkan setiap masalah perangkat kepada orang lain tanpa mau mencoba sendiri, dan jarang belajar dari cara mereka memperbaikinya"],answer:0,explain:"Melek digital = paham konsep dasar + bisa bertindak + tahu batas. Bukan sekadar hafal istilah.",hint:"Paham + bisa bertindak + tahu batas, atau hafal istilah / selalu bergantung?"},
{n:98,type:"mcq",micro:"Perangkat & keberlanjutan",q:"Kebiasaan pemakaian perangkat yang lebih bertanggung jawab pada lingkungan:",options:["Beli sebanyak mungkin perangkat baru setiap ada kesempatan, simpan tanpa dipakai, dan jangan memperbaiki atau mendaur ulang perangkat rusak","Rawat & pakai perangkat lebih lama, perbaiki bila bisa, daur ulang elektronik dengan benar (bukan sampah biasa), & hindari mengganti hanya karena tren","Ganti perangkat tiap tahun mengikuti tren dan buang yang lama ke tempat sampah biasa, karena elektronik tidak mengandung bahan yang berbahaya bagi lingkungan sekitar"],answer:1,explain:"Membuat & membuang elektronik berdampak besar pada lingkungan. Memakai lebih lama & mendaur ulang benar mengurangi dampak itu.",hint:"Pakai lama + perbaiki + daur ulang, atau ganti tiap tahun & buang?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'perangkat & internet dasar':",options:["Menghafal semua istilah teknis tentang perangkat dan internet, tanpa perlu bisa memakainya, merawatnya, memecahkan masalah, atau membuat pilihan yang aman dan hemat dalam kehidupan sehari-hari","Memakai perangkat sebanyak mungkin setiap hari tanpa batas waktu, mengikuti semua tren, dan menyerahkan semua masalah teknis kepada orang lain tanpa mencoba memahaminya sendiri sedikit pun","Paham konsep dasar (perangkat, koneksi, server/klien, penyimpanan, akun), bisa memakai & merawatnya, memecahkan masalah umum secara bertahap, membuat pilihan yang aman & hemat, & tahu kapan minta bantuan"],answer:2,explain:"Tujuannya menjadi pemakai yang berdaya & bijak: mengerti secukupnya, bisa bertindak, aman, & sadar batas, bukan ahli teknis maupun pemakai yang bingung.",hint:"Paham + bisa + aman + tahu batas, atau hafal istilah / pakai sebanyak mungkin?"},
{n:100,type:"open",micro:"Kapstone: panduan perangkat pribadi",q:"Buat 'panduan perangkat pribadi' untuk dirimu sendiri (atau adik). Sertakan: (a) daftar perangkat & bagaimana masing-masing terhubung ke internet, (b) rutinitas perawatan (harian/mingguan/bulanan), (c) langkah pemecahan untuk 4 masalah umum, (d) daftar 'tanda bahaya, minta bantuan dewasa', (e) 3 kebiasaan aman (izin, sumber unduhan, jaringan publik, cadangan, dll), (f) satu kebiasaan keseimbangan (waktu/tempat tanpa perangkat).",explain:"Jawaban baik: daftar perangkat dengan cara koneksi yang benar, rutinitas perawatan berjenjang (harian/mingguan/bulanan) yang realistis, langkah pemecahan bertahap & benar untuk 4 masalah umum, daftar tanda bahaya yang konkret & sesuai (fisik + penipuan + akun), 3 kebiasaan aman yang spesifik, & satu kebiasaan keseimbangan yang nyata.",hint:"Buat bagian (c) benar-benar berupa langkah berurutan yang bisa diikuti, dan (d) berisi hal-hal konkret yang tidak boleh dicoba sendiri.",sample:"PANDUAN PERANGKATKU. (a) Perangkat: HP Android (Wi-Fi rumah/sekolah, data seluler paket 10GB/bulan di jalan), laptop sekolah (Wi-Fi saja), HP lama (dipakai luring sebagai jam & pemutar musik). (b) Perawatan: Harian, isi daya saat nyaman jangan sampai 0%, tutup tab browser yang menumpuk. Mingguan, hapus file di folder Unduhan yang tidak dipakai, cek foto ganda, restart HP sekali. Bulanan, audit lengkap, penyimpanan, aplikasi tak terpakai dicopot, tinjau izin & notifikasi, pastikan sistem & aplikasi terbarui, cek cadangan foto ke cloud berjalan. (c) Pemecahan masalah: 1. Internet lambat, cek mode pesawat, matikan-nyalakan Wi-Fi, restart HP, coba situs lain, restart router. 2. Aplikasi menutup sendiri, tutup & buka lagi, restart HP, perbarui aplikasi, bersihkan cache-nya. 3. Penyimpanan penuh, Pengaturan > Penyimpanan, hapus unduhan lama & video besar & cache, pindahkan foto ke cloud. 4. Baterai boros, turunkan kecerahan + mode hemat daya, cek aplikasi boros di Pengaturan > Baterai, matikan lokasi/Bluetooth bila tidak dipakai. (d) Tanda bahaya, minta bantuan dewasa: HP/laptop tidak mau menyala, layar retak, baterai menggembung atau sangat panas atau berbau, muncul permintaan pembayaran/kata sandi yang tidak kukenali, pesan 'perangkat terinfeksi' yang menakutkan, atau akun tiba-tiba tidak bisa dibuka. (e) Kebiasaan aman: (1) hanya memasang aplikasi dari toko resmi & memeriksa izin, menolak izin yang tidak sesuai fungsi. (2) Tidak login ke akun penting atau membuka hal pribadi lewat Wi-Fi publik yang tak dikenal, pakai data seluler untuk itu. (3) Menyalakan cadangan otomatis foto & dokumen penting ke cloud, & sesekali cek cadangannya benar berjalan. (f) Kebiasaan keseimbangan: tidak membawa HP ke tempat tidur, mengisi dayanya di ruang lain semalaman & memakai HP lama sebagai jam alarm."},
];
